const require_is = require("./is.js");
//#region src/utils/domTarget.ts
function getTargetElement(target, defaultElement) {
	if (!require_is.isBrowser) return;
	if (!target) return defaultElement;
	let targetElement;
	if (require_is.isFunction(target)) targetElement = target();
	else if ("current" in target) targetElement = target.current;
	else targetElement = target;
	return targetElement;
}
//#endregion
exports.getTargetElement = getTargetElement;
